BARR=["bartender"]
DRAM="https://www.revisor.mn.gov/statutes/cite/340A.801"; AGE="https://www.revisor.mn.gov/statutes/cite/340A.503"; INTOX="https://www.revisor.mn.gov/statutes/cite/340A.502"
NIAAA="https://www.niaaa.nih.gov/alcohols-effects-health/alcohol-topics/alcohol-facts-and-statistics/what-standard-drink"
CDCA="https://www.cdc.gov/alcohol/standard-drink-sizes/index.html"
add(BARR,"role",[
("id","easy","In Minnesota, which of these is valid proof of age to buy alcohol?","En Minnesota, ¿cuál es prueba válida de edad para comprar alcohol?",["A valid driver's license or state ID with photo and birth date","A student ID","A credit card","A photo on their phone"],["Una licencia o ID estatal válida con foto y fecha de nacimiento","Una credencial escolar","Una tarjeta de crédito","Una foto en el teléfono"],"Minn. Stat. 340A.503 subd. 6 lists accepted IDs.","La ley 340A.503 subd. 6 enumera las IDs aceptadas.",AGE),
("id","med","Besides a driver's license or state ID, which ID does Minnesota law accept for alcohol?","Además de licencia o ID estatal, ¿qué ID acepta la ley de Minnesota?",["A valid U.S. passport or U.S. military ID","A library card","A gym membership card","A business card"],["Pasaporte de EE. UU. o ID militar de EE. UU. válidos","Tarjeta de biblioteca","Tarjeta del gimnasio","Tarjeta de presentación"],"340A.503 subd. 6 also allows a U.S. passport, DoD military ID, and a foreign national's valid passport.","También acepta pasaporte de EE. UU., ID militar y pasaporte de extranjeros.",AGE),
("id","hard","A guest turns 21 today. When can you legally serve them in Minnesota?","Un huésped cumple 21 hoy. ¿Desde cuándo puedes servirle?",["8:00 a.m. on their 21st birthday","Midnight","Noon","Only tomorrow"],["8:00 a.m. del día que cumple 21","Medianoche","Mediodía","Hasta mañana"],"340A.503 subd. 5a: a person isn't 21 until 8 a.m. on their birthday.","340A.503 subd. 5a: no tiene 21 hasta las 8 a.m. de su cumpleaños.",AGE),
("id","med","You believe an ID is fake. What may a licensed retailer do in Minnesota?","Crees que una ID es falsa. ¿Qué puede hacer el establecimiento?",["Refuse service; it may seize the ID and must give it to police within 24 hours","Keep it as a souvenir","Serve anyway","Throw it away"],["Negar servicio; puede retenerla y debe entregarla a la policía en 24 horas","Guardarla de recuerdo","Servir igual","Tirarla"],"340A.503 subd. 6(c) allows seizure with delivery to law enforcement within 24 hours.","340A.503 subd. 6(c) permite retenerla y entregarla en 24 horas.",AGE),
("id","easy","A 21-year-old orders two drinks; their 19-year-old friend is with them. What do you do?","Alguien de 21 pide dos tragos y su amigo de 19 está con él. ¿Qué haces?",["Serve only the of-age guest one drink and watch for passing it to the minor","Serve both drinks","Serve both if they're nice","Let the 19-year-old pay"],["Servir solo al mayor de edad y vigilar que no se lo pase","Servir ambos","Servir si son amables","Que pague el de 19"],"Furnishing alcohol to anyone under 21 is illegal under 340A.503.","Dar alcohol a menores de 21 es ilegal (340A.503).",AGE),
("intox","med","Minnesota law says you may not sell alcohol to someone who is:","La ley de Minnesota prohibe vender alcohol a alguien que está:",["Obviously intoxicated","Wearing a hat","From another state","Paying cash"],["Obviamente intoxicado","Con sombrero","De otro estado","Pagando en efectivo"],"Minn. Stat. 340A.502 bans sales to obviously intoxicated persons.","La ley 340A.502 lo prohibe.",INTOX),
("intox","med","Which is a common sign a guest may be intoxicated?","¿Señal común de que alguien está intoxicado?",["Slurred speech or stumbling","Ordering water","Asking for the menu","Paying with a card"],["Habla arrastrada o tropezar","Pedir agua","Pedir el menú","Pagar con tarjeta"],"Watch behavior, not just drink count.","Observa la conducta, no solo cuántos tragos.",BP),
("intox","hard","Why does refusing an obviously drunk guest matter beyond the law?","¿Por qué importa negarle a alguien muy borracho, además de la ley?",["Under dram shop law the bar can be liable for harm they cause","It doesn't","It saves ice","It speeds up closing"],["Por la ley 'dram shop', el bar puede ser responsable del daño que cause","No importa","Ahorra hielo","Cierra más rápido"],"Minn. Stat. 340A.801 lets injured people sue for illegal sales.","La ley 340A.801 permite demandar por ventas ilegales.",DRAM),
("intox","med","How should you cut off a guest?","¿Cómo dejas de servirle a alguien?",["Privately and calmly, offer water or food, and help arrange a safe ride","Loudly in front of everyone","By pouring weaker drinks secretly","By ignoring them until they leave"],["En privado y con calma, ofrecer agua o comida y ayudar con transporte seguro","En voz alta frente a todos","Sirviendo tragos más débiles a escondidas","Ignorándolo hasta que se vaya"],"A calm, private cutoff reduces conflict; tell your manager.","Hacerlo en privado reduce conflictos; avisa al gerente.",BP),
("intox","easy","A guest you cut off asks a friend to order for them. You:","Alguien a quien ya no sirves le pide a un amigo que pida por él. Tú:",["Don't serve drinks meant for the cut-off guest","Serve the friend double","Serve if the friend tips","Let it slide"],["No servir tragos para la persona cortada","Servir doble al amigo","Servir si da propina","Dejarlo pasar"],"Serving through a friend is still serving the intoxicated person.","Servir por medio de otro sigue siendo servirle.",INTOX),
("drinks","easy","In the U.S., a standard drink has about how much pure alcohol?","En EE. UU., una bebida estándar tiene cuánto alcohol puro?",["14 grams (0.6 oz)","5 grams","30 grams","50 grams"],["14 gramos (0.6 oz)","5 gramos","30 gramos","50 gramos"],"NIAAA: one standard drink = 14 g of pure alcohol.","NIAAA: una bebida estándar = 14 g de alcohol puro.",NIAAA),
("drinks","med","Which equals about one standard drink?","¿Cuál equivale a una bebida estándar?",["12 oz of regular beer (about 5%)","A 24 oz craft IPA","A full bottle of wine","A double shot"],["12 oz de cerveza normal (aprox. 5%)","Una IPA de 24 oz","Una botella de vino","Un trago doble"],"CDC: 12 oz beer at 5%, 5 oz wine at 12%, 1.5 oz spirits at 40%.","CDC: 12 oz cerveza 5%, 5 oz vino 12%, 1.5 oz destilado 40%.",CDCA),
("drinks","med","A standard pour of 80-proof liquor is:","Una porción estándar de licor de 40% es:",["1.5 oz","3 oz","0.5 oz","6 oz"],["1.5 oz","3 oz","0.5 oz","6 oz"],"CDC: 1.5 oz of 40% spirits is one standard drink.","CDC: 1.5 oz de destilado 40% es una bebida estándar.",CDCA),
("drinks","easy","A standard glass of wine (12%) is:","Una copa estándar de vino (12%) es:",["5 oz","10 oz","2 oz","8 oz"],["5 oz","10 oz","2 oz","8 oz"],"CDC: 5 oz of 12% wine is one standard drink.","CDC: 5 oz de vino 12% es una bebida estándar.",CDCA),
("drinks","med","Why should you know a craft beer's alcohol content?","¿Por qué conocer el alcohol de una cerveza artesanal?",["Strong beers can equal 2 or more standard drinks","It doesn't matter","To set the price only","For the glass color"],["Las cervezas fuertes pueden ser 2 o más bebidas estándar","No importa","Solo para el precio","Por el color del vaso"],"Higher ABV and bigger pours add up fast.","Más grados y más tamaño suman rápido.",CDCA),
("cash","med","At bar close, what should match your sales report?","Al cerrar el bar, ¿qué debe coincidir con el reporte de ventas?",["Cash plus card totals, after removing the starting bank","Only the tip jar","The number of glasses","Nothing"],["Efectivo más tarjetas, quitando el fondo inicial","Solo el bote de propinas","El número de vasos","Nada"],"Over/short means something was missed or rung wrong.","Sobrante/faltante indica un error.",BP),
("cash","med","A comp or void at the bar needs:","Una cortesía o anulación en el bar necesita:",["A reason and manager approval per policy","Nothing","A guest's signature only","To be hidden"],["Razón y aprobación del gerente según la política","Nada","Solo firma del huésped","Ocultarse"],"Approved, logged comps keep inventory and cash accurate.","Cortesías aprobadas y registradas mantienen el control.",BP),
("cash","easy","When should you ring a drink into the register?","¿Cuándo registras un trago en la caja?",["Before or as you serve it, every time","At the end of the night","Only for big tabs","Never for regulars"],["Antes o al servirlo, siempre","Al final de la noche","Solo cuentas grandes","Nunca a clientes frecuentes"],"Every drink rung in keeps counts and cash matched.","Registrar todo cuadra inventario y caja.",BP),
("inventory","med","Why do bars track pour cost or variance?","¿Por qué el bar mide costo o variación?",["To catch over-pouring, waste, or theft","To pick music","To set hours","To count guests"],["Para detectar porciones grandes, desperdicio o robo","Para elegir música","Para el horario","Para contar clientes"],"Variance shows inventory that's missing compared to sales.","La variación muestra inventario faltante vs. ventas.",BP),
("inventory","easy","Which tool helps keep pours consistent?","¿Qué ayuda a servir porciones iguales?",["A jigger or measured pour spout","Eyeballing","A coffee mug","Pouring until the glass is full"],["Un jigger o pico medidor","Al tanteo","Una taza","Llenar el vaso"],"Measured pours control cost and help guests drink responsibly.","Medir controla costo y ayuda al consumo responsable.",BP),
("food_safety","med","How should you scoop ice for drinks?","¿Cómo sacas hielo para bebidas?",["With a clean scoop that has a handle, never the glass","With the glass","With your hand","With a cup from the trash area"],["Con pala limpia con mango, nunca con el vaso","Con el vaso","Con la mano","Con un vaso cualquiera"],"FDA Food Code: ice is food; glasses can chip and contaminate it.","Código FDA: el hielo es alimento; el vaso puede romperse.",FC),
("food_safety","hard","A glass breaks in the ice bin. What do you do?","Se rompe un vaso en el hielo. ¿Qué haces?",["Empty and melt all the ice, clean and sanitize the bin, then refill","Pick out the big pieces","Keep using it carefully","Cover it with fresh ice"],["Vaciar y derretir todo el hielo, limpiar y desinfectar, y rellenar","Sacar los pedazos grandes","Seguir usándolo con cuidado","Cubrirlo con hielo nuevo"],"Tiny glass shards can't be seen — 'burn' the whole bin.","No se ven los pedacitos; hay que tirar todo el hielo.",FC),
("food_safety","easy","Garnish fruit should be handled with:","La fruta para decorar se manipula con:",["Tongs, picks, or gloves — not bare hands","Bare hands","The ice scoop","Your teeth"],["Pinzas, palillos o guantes, no con la mano","Mano desnuda","La pala de hielo","Los dientes"],"Food Code limits bare-hand contact with ready-to-eat food.","El código limita el contacto con alimentos listos.",FC),
("food_safety","med","How long can cut citrus garnish sit out at room temperature?","¿Cuánto puede estar fruta cortada a temperatura ambiente?",["Follow your hotel's time limit and discard at end of shift","Forever","A week","Until it turns brown"],["Seguir el límite del hotel y tirarla al final del turno","Siempre","Una semana","Hasta que se ponga café"],"Date and discard per your bar's procedure.","Fecha y desecha según el procedimiento.",BP),
("service","easy","A guest asks for a drink you don't know how to make. Best reply?","Piden un trago que no sabes preparar. ¿Mejor respuesta?",["Be honest, ask how they like it or suggest something close","Pretend and guess","Say it doesn't exist","Ignore them"],["Ser honesto, preguntar cómo le gusta o sugerir algo similar","Fingir y adivinar","Decir que no existe","Ignorarlo"],"Honesty plus a good suggestion keeps trust.","Honestidad y una buena sugerencia generan confianza.",BP),
("service","med","A guest wants to start a tab. What do you hold?","Alguien quiere abrir una cuenta. ¿Qué guardas?",["Follow policy: pre-authorize a card or charge to the room after verifying the guest","Their phone","Their car keys","Nothing"],["Según la política: preautorizar tarjeta o cargar al cuarto verificando al huésped","Su teléfono","Sus llaves","Nada"],"Verified tabs prevent walkouts.","Las cuentas verificadas evitan que se vayan sin pagar.",BP),
("service","med","A guest asks you to charge drinks to room 214. What do you check?","Piden cargar tragos al cuarto 214. ¿Qué verificas?",["Name and room match the registered guest (key or ID)","Nothing","Only the room number","Their age only"],["Que nombre y cuarto coincidan con el huésped registrado (llave o ID)","Nada","Solo el número","Solo la edad"],"Prevents charging the wrong guest.","Evita cargar al huésped equivocado.",BP),
("safety","easy","A guest who's been drinking wants to drive. Best response?","Alguien que ha tomado quiere manejar. ¿Mejor respuesta?",["Offer a rideshare, taxi, or remind them their room is upstairs","Give them coffee and send them off","Ignore it","Serve one more for the road"],["Ofrecer taxi o app, o recordarle que su cuarto está arriba","Darle café y despedirlo","Ignorarlo","Servir uno más"],"Coffee doesn't sober people up; only time does.","El café no quita lo borracho; solo el tiempo.",NHTSA),
("safety","med","A fight starts at the bar. What do you do?","Empieza una pelea en el bar. ¿Qué haces?",["Stay out of it physically, call the manager and 911 if needed","Jump in to separate them","Keep serving","Film it"],["No meterte físicamente, llamar al gerente y al 911 si hace falta","Meterte a separarlos","Seguir sirviendo","Grabarlo"],"Your safety first; let police handle violence.","Primero tu seguridad; la policía maneja la violencia.",BP),
])
